// Parse Relay transaction email
const email = $input.first().json;
const subject = email.subject || '';
const body = email.text || email.snippet || '';

// Extract amount from subject: "Card transaction: $45.00 at OpenAI"
const amountMatch = subject.match(/\$([0-9,]+\.?[0-9]*)/);
const amount = amountMatch 
  ? parseFloat(amountMatch[1].replace(',', '')) 
  : 0;

// Extract merchant from subject
let merchant = 'Unknown Merchant';
const merchantMatch = subject.match(/at\s+(.+?)(?:\s*$|\s+on)/i);
if (merchantMatch) {
  merchant = merchantMatch[1].trim();
} else {
  // Try alternate pattern: "$XX.XX by Merchant"
  const altMatch = subject.match(/by\s+(.+?)(?:\s*$|\s+on)/i);
  if (altMatch) {
    merchant = altMatch[1].trim();
  }
}

// Clean merchant name
merchant = merchant.replace(/[*#]+/g, '').trim();

// Extract date from body
let transactionDate = new Date().toISOString().split('T')[0];
const datePatterns = [
  /on\s+([A-Z][a-z]+\s+\d{1,2},?\s+\d{4})/i,
  /Date:\s*([A-Z][a-z]+\s+\d{1,2},?\s+\d{4})/i,
  /(\d{1,2}\/\d{1,2}\/\d{2,4})/,
  /([A-Z][a-z]+\s+\d{1,2},?\s+\d{4})/i
];

for (const pattern of datePatterns) {
  const dateMatch = body.match(pattern) || subject.match(pattern);
  if (dateMatch) {
    try {
      const parsed = new Date(dateMatch[1]);
      if (!isNaN(parsed.getTime())) {
        transactionDate = parsed.toISOString().split('T')[0];
        break;
      }
    } catch (e) {}
  }
}

// Extract card last 4 digits
const cardMatch = body.match(/ending in (\d{4})/) || body.match(/\*{4}\s*(\d{4})/) || subject.match(/\*+(\d{4})/);
const cardLast4 = cardMatch ? cardMatch[1] : '';

// Generate unique transaction ID
const timestamp = Date.now();
const transactionId = `relay_${cardLast4 || 'xxxx'}_${timestamp}`;

// Calculate validation deadline (24 hours from now)
const deadline = new Date();
deadline.setHours(deadline.getHours() + 24);
const validationDeadline = deadline.toISOString();

return [{
  json: {
    amount,
    merchant,
    transactionDate,
    cardLast4,
    transactionId,
    validationDeadline,
    source: 'Relay Card',
    emailId: email.id,
    rawSubject: subject,
    rawBody: body.substring(0, 500)
  }
}];

